/* Hverdagsro – Mit værelse: the things a child can earn for their room, in packs. All drawn here, in the room's own
   style (thick outline, bright colours). Every theme is our own: no characters or brands from films, shows or bands.
   Each thing is drawn from its bottom centre (0,0) upwards; c is its colour (the child can change it). */

export const OL = "#2B2340";
/* The outline; o may set its own stroke and stroke-width (an attribute given twice would be dropped by the parser). */
export const S = (o = "") => {
  let st = OL, sw = "4";
  const rest = String(o)
    .replace(/(^|\s)stroke="([^"]*)"/g, (_, a, v) => ((st = v), ""))
    .replace(/(^|\s)stroke-width="([^"]*)"/g, (_, a, v) => ((sw = v), ""))
    .trim();
  return `stroke="${st}" stroke-width="${sw}" stroke-linejoin="round" stroke-linecap="round"${rest ? " " + rest : ""}`;
};
export const shade = (hex, k) => {
  const n = parseInt(String(hex).slice(1), 16);
  const f = (v) => Math.max(0, Math.min(255, Math.round(v * k)));
  return "#" + [f(n >> 16), f((n >> 8) & 255), f(n & 255)].map((v) => v.toString(16).padStart(2, "0")).join("");
};
const T3 = 'stroke-width="3"';
const r = (x, y, w, h, f, rx = 6, o = "") => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${f}" ${S(o)}/>`;
const c = (cx, cy, R, f, o = "") => `<circle cx="${cx}" cy="${cy}" r="${R}" fill="${f}" ${S(o)}/>`;
const e = (cx, cy, rx, ry, f, o = "") => `<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="${f}" ${S(o)}/>`;
const p = (d, f = "none", o = "") => `<path d="${d}" fill="${f}" ${S(o)}/>`;
const ln = (d, col, w = 6) => `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const dot = (cx, cy, R, f) => `<circle cx="${cx}" cy="${cy}" r="${R}" fill="${f}"/>`;
const gl = (cx, cy, rx, ry, col = "#FFE8A3") => `<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" class="pl-glow" fill="${col}"/>`;
const L = (inner) => `<g class="pl-lamp">${inner}</g>`;
const tx = (x, y, s, size = 24, f = OL, o = "") => `<text x="${x}" y="${y}" font-size="${size}" font-weight="900" text-anchor="middle" fill="${f}" font-family="system-ui, sans-serif" ${o}>${s}</text>`;
const star = (cx, cy, R, f, o = T3) => {
  const pts = Array.from({ length: 10 }, (_, i) => {
    const a = -Math.PI / 2 + (i * Math.PI) / 5, rr = i % 2 ? R * 0.45 : R;
    return `${(cx + Math.cos(a) * rr).toFixed(1)},${(cy + Math.sin(a) * rr).toFixed(1)}`;
  }).join(" ");
  return `<polygon points="${pts}" fill="${f}" ${S(o)}/>`;
};
const heart = (cx, cy, s, f, o = T3) => p(`M${cx} ${cy + 14 * s} C${cx - 26 * s} ${cy - 2 * s} ${cx - 16 * s} ${cy - 22 * s} ${cx - 4 * s} ${cy - 18 * s} C${cx - 1 * s} ${cy - 17 * s} ${cx} ${cy - 14 * s} ${cx} ${cy - 12 * s} C${cx} ${cy - 14 * s} ${cx + 1 * s} ${cy - 17 * s} ${cx + 4 * s} ${cy - 18 * s} C${cx + 16 * s} ${cy - 22 * s} ${cx + 26 * s} ${cy - 2 * s} ${cx} ${cy + 14 * s}Z`, f, o);
const paw = (cx, cy, s, f) => `${e(cx, cy + 6 * s, 12 * s, 10 * s, f, T3)}${[-14, -5, 5, 14].map((x, i) => e(cx + x * s, cy - (i === 0 || i === 3 ? 8 : 14) * s, 5 * s, 6 * s, f, T3)).join("")}`;
const rep = (n, fn) => Array.from({ length: n }, (_, i) => fn(i)).join("");
const leaf = (x, y, a, f = "#6BCB77", s = 1) => `<path d="M0 0 C${12 * s} ${-14 * s} ${34 * s} ${-12 * s} ${48 * s} 0 C${34 * s} ${12 * s} ${12 * s} ${14 * s} 0 0Z" fill="${f}" ${S(T3)} transform="translate(${x} ${y}) rotate(${a})"/>`;

